/**
 * Unit tests for MathArrays.linearCombination.
 */
public class MathArrays_linearCombination_TriageGen1Test {

    private static final double DELTA = 1e-12;









    @Test
    public void testLinearCombination_NaNFallback() throws DimensionMismatchException {
        // Trigger the NaN check logic
        // The code uses a fallback to naive implementation if result is NaN
        double[] a = {Double.NaN, 1.0};
        double[] b = {1.0, 1.0};

        // The fallback loop: result = 0; for (i=0; i<len; i++) result += a[i]*b[i];
        // NaN * 1.0 = NaN. 0 + NaN = NaN. 
        // However, if we use values that produce NaN in the complex math but not in naive:
        // Let's use Infinity to try and force NaN via (inf - inf)
        double[] aInf = {Double.POSITIVE_INFINITY, 1.0};
        double[] bInf = {Double.POSITIVE_INFINITY, 1.0};

        // The complex math will likely produce NaN due to infinity arithmetic.
        // The fallback will calculate: Inf * Inf + 1 * 1 = Inf.
        double result = MathArrays.linearCombination(aInf, bInf);

        // If the complex math resulted in NaN, the fallback returns Inf.
        // If the complex math resulted in Inf, it returns Inf.
        // To specifically test the 'if (Double.isNaN(result))' branch, 
        // we need a scenario where the complex math produces NaN but the naive doesn't.
        // Since a[i]*b[i] is part of the complex math, it's hard to avoid NaN in both 
        // unless the split logic causes it.

        double[] aNaN = {Double.NaN, 1.0};
        double[] bNaN = {1.0, 1.0};
        double resultNaN = MathArrays.linearCombination(aNaN, bNaN);
        // Naive: 0 + (NaN * 1) + (1 * 1) = NaN
        assertEquals(Double.NaN, resultNaN, 0.0);
    }




}

